 const preview=$('#productImagePreview'),fileInput=$('#productImageInput'),unitsInput=$('#unitsPerPurchase'),packageInput=$('#packageBuyPrice'),baseUnitSelect=$('#productForm [name="baseUnit"]'),conversionToggle=$('#unitConversionEnabled');
