function openCategoryManager(){
 openModal('دسته‌بندی کالا','<form id="categoryForm" class="modal-form"><label class="field"><span>دسته‌بندی جدید</span><div style="display:flex;gap:7px"><input name="name" placeholder="مثلاً لبنیات" style="flex:1" required><button class="primary-btn">افزودن</button></div></label><div id="categoryChipList" class="category-chip-list"></div></form>');
 function redraw(){const box=$('#categoryChipList');box.innerHTML=db.categories.map(function(c){const used=db.products.filter(function(p){return p.categoryId===c.id}).length;return '<span class="category-chip"><b>'+esc(c.name)+'</b><small>'+num(used)+'</small>'+(c.id!=='cat-general'?'<button type="button" data-cat="'+c.id+'" title="حذف">×</button>':'')+'</span>'}).join('');$$('[data-cat]').forEach(function(b){b.onclick=function(){const cid=b.dataset.cat,cat=db.categories.find(function(c){return c.id===cid}),usedCount=db.products.filter(function(p){return p.categoryId===cid}).length;if(!cat)return;openModal('حذف دسته‌بندی','<div class="confirm-card danger-confirm"><div class="confirm-icon">!</div><h4>دسته «'+esc(cat.name)+'» حذف شود؟</h4><p>'+(usedCount?('این دسته روی '+num(usedCount)+' کالا استفاده شده است. با حذف دسته، این کالاها به دسته «عمومی» منتقل می‌شوند.'):'پس از تأیید، این دسته‌بندی حذف می‌شود.')+'</p><div class="modal-actions"><button id="cancelDeleteCategory" class="ghost-btn">انصراف</button><button id="confirmDeleteCategory" class="danger-btn">تأیید و حذف</button></div></div>');$('#cancelDeleteCategory').onclick=closeModal;$('#confirmDeleteCategory').onclick=function(){db.products.forEach(function(p){if(p.categoryId===cid)p.categoryId='cat-general'});db.categories=db.categories.filter(function(c){return c.id!==cid});if(save()){closeModal();toast('دسته «'+cat.name+'» حذف شد');renderProducts();renderCategoryOptions();}}}})}redraw();$('#categoryForm').onsubmit=function(e){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim();if(!name)return;if(db.categories.some(function(c){return normalizeText(c.name)===normalizeText(name)})){toast('این دسته‌بندی قبلاً وجود دارد');return}db.categories.push({id:id('cat'),name:name});save();e.target.reset();redraw()}
}
